import copy


class StateMachine:
    def __init__(self, transitions, initial_state, *, guards=None, actions=None):
        self._transitions = dict(copy.deepcopy(transitions))
        self._guards = dict(copy.deepcopy(guards)) if guards else {}
        self._actions = dict(copy.deepcopy(actions)) if actions else {}
        self._state = initial_state
        self._in_callback = False

    def current(self):
        return self._state

    def can_trigger(self, event):
        return (self._state, event) in self._transitions

    def trigger(self, event, **payload):
        key = (self._state, event)
        if key not in self._transitions:
            raise ValueError(f"No transition for state {self._state!r} on event {event!r}")
        if self._in_callback:
            raise RuntimeError("Nested trigger during callback is not allowed")

        old_state = self._state
        new_state = self._transitions[key]

        guard = self._guards.get(key)
        if guard is not None:
            self._in_callback = True
            try:
                allowed = guard(old_state, event, dict(payload))
            finally:
                self._in_callback = False
            if not allowed:
                raise ValueError(f"Guard rejected event {event!r} in state {old_state!r}")

        action = self._actions.get(key)
        if action is not None:
            self._in_callback = True
            try:
                action(old_state, new_state, event, dict(payload))
            finally:
                self._in_callback = False

        self._state = new_state
        return new_state
